#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Issue #324: buy the Databento history, import it, and start the IBKR stock split check.
# Run it on the server, in the ATrade directory, in a terminal multiplexer (for example zellij),
# because the import and the waits for Databento can take a long time.
#
#   ./scripts/databento-history-wizard.sh
#
# You can stop it with Ctrl-C and run it again. It does not buy a job again: the job IDs are in
# data/databento/<daily|hourly>/jobs.txt. A second import of the same files adds no row.

ATRADE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ATRADE_DIR"
ENV_FILE="$ATRADE_DIR/.env"
DAILY_DIR="$ATRADE_DIR/data/databento/daily"
HOURLY_DIR="$ATRADE_DIR/data/databento/hourly"
SPLIT_CHECK_CONTAINER="atrade-ibkr-split-check"
# The merge commit of #333: the import without IBKR and the program atrade.app.ibkr_split_check.
REQUIRED_COMMIT="6fb6d5b"
MIN_FREE_GB=40
POLL_SECONDS=60

dc() { docker compose --file deploy/compose.yaml --env-file "$ENV_FILE" "$@"; }

# Runs Python in a temporary web container. The web container gets DATABENTO_API_KEY and the database settings.
web_python() { dc run --rm -T web python -c "$1" "${@:2}"; }

psql_query() { dc exec -T postgres psql -U atrade -d atrade -c "$1"; }

# The 5 batch jobs of the daily purchase (docs/architecture/market_data.md section 8.8.1). With "submit", the
# arguments after the mode are the "dataset/schema" keys that have a job already.
DAILY_JOBS_PY='
import sys
import databento
client = databento.Historical()
# The end of one schema can be earlier than the end of the dataset, for example ohlcv-1d ends at 00:00 UTC of today.
def schema_end(dataset, schema):
    dataset_range = client.metadata.get_dataset_range(dataset=dataset)
    return dataset_range.get("schema", {}).get(schema, {}).get("end") or dataset_range["end"][:10]
summary_end = schema_end("EQUS.SUMMARY", "ohlcv-1d")
jobs = [
    ("XNAS.ITCH", "ohlcv-1d", "2018-05-01", "2024-07-01"),
    ("XNYS.PILLAR", "ohlcv-1d", "2018-05-01", "2024-07-01"),
    ("XNAS.ITCH", "statistics", "2018-05-01", "2024-07-01"),
    ("XNYS.PILLAR", "statistics", "2018-05-01", "2024-07-01"),
    ("EQUS.SUMMARY", "ohlcv-1d", "2024-07-01", summary_end),
]
mode = sys.argv[1]
done = set(sys.argv[2:])
total = 0.0
for dataset, schema, start, end in jobs:
    key = f"{dataset}/{schema}"
    if mode == "cost":
        cost = client.metadata.get_cost(dataset=dataset, schema=schema, symbols="ALL_SYMBOLS", start=start, end=end)
        total += cost
        print(f"  {dataset:13} {schema:11} {start} to {str(end)[:10]}: {cost:8.2f} USD")
    elif key not in done:
        job = client.batch.submit_job(
            dataset=dataset, schema=schema, symbols="ALL_SYMBOLS", start=start, end=end,
            encoding="dbn", compression="zstd", split_duration="month",
        )
        print(key, job["id"], flush=True)
if mode == "cost":
    print(f"  Total: {total:.2f} USD")
'

# The hourly purchase: one batch job for each quarter of the universe (section 8.8.1). With "submit", the arguments
# after the mode are the quarter starts that have a job already.
HOURLY_JOBS_PY='
import sys
from datetime import UTC, date, datetime
import databento
from atrade.foundation.settings import Settings
from atrade.market_data import list_hourly_purchases
client = databento.Historical()
dataset_range = client.metadata.get_dataset_range(dataset="XNAS.ITCH")
hourly_end = dataset_range.get("schema", {}).get("ohlcv-1h", {}).get("end") or dataset_range["end"]
available_end = date.fromisoformat(hourly_end[:10])
end_day = min(datetime.now(UTC).date(), available_end)
purchases = list_hourly_purchases(database_url=Settings().database_url, end_day=end_day)
done = set(sys.argv[2:])
for purchase in purchases:
    if purchase.start.isoformat() in done:
        continue
    job = client.batch.submit_job(
        dataset="XNAS.ITCH", schema="ohlcv-1h", symbols=purchase.symbols,
        start=purchase.start.isoformat(), end=purchase.end.isoformat(),
        encoding="dbn", compression="zstd", split_duration="month",
    )
    print(purchase.start.isoformat(), job["id"], flush=True)
print(f"QUARTERS {len(purchases)}", flush=True)
'

# Prints the state of each job. Exits 0 when all jobs are done.
JOB_STATE_PY='
import sys
import databento
client = databento.Historical()
wanted = set(sys.argv[1:])
states = {job["id"]: job["state"] for job in client.batch.list_jobs(states="queued,processing,done,expired")}
missing = "not found"
for job_id in sorted(wanted):
    print(f"  {job_id}: {states.get(job_id, missing)}")
sys.exit(0 if all(states.get(job_id) == "done" for job_id in wanted) else 1)
'

# The job IDs of a jobs.txt file. Each line is "<key> <job ID>": the key is "dataset/schema" or the quarter start.
read_job_ids() { [[ -f "$1" ]] && awk '{print $NF}' "$1" | grep -v '^$' || true; }

wait_for_jobs() {
  local -a ids
  mapfile -t ids < <(read_job_ids "$1")
  (( ${#ids[@]} )) || { warn "No job IDs in $1."; return 1; }
  say "Databento prepares the files. This can take minutes to hours. The wizard checks every ${POLL_SECONDS} s."
  until web_python "$JOB_STATE_PY" "${ids[@]}"; do
    note "Not all jobs are done. Next check in ${POLL_SECONDS} s. (Ctrl-C stops the wizard. The jobs continue.)"
    sleep "$POLL_SECONDS"
  done
  printf '  %s✓ all %d jobs are done%s\n' "$GREEN" "${#ids[@]}" "$RESET"
}

# Downloads each job that has no folder yet, then imports all DBN files of the directory (no IBKR request).
import_directory() {
  local dir="$1" job_id
  local -a args=()
  while read -r job_id; do
    [[ -n "$job_id" ]] || continue
    if compgen -G "$dir/$job_id/*.dbn*" >/dev/null; then
      note "Job $job_id is downloaded already."
    else
      args+=(--job-id "$job_id")
    fi
  done < <(read_job_ids "$dir/jobs.txt")
  dc run --rm --user "$(id -u):$(id -g)" -v "$dir:/databento" web \
    python -m atrade.app.databento_import /databento "${args[@]}"
}

run_wizard() {

TOTAL_STAGES=10

banner "ATrade: Databento history and IBKR stock split check (#324)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the server"
say "Directory: $ATRADE_DIR"
if ! git merge-base --is-ancestor "$REQUIRED_COMMIT" HEAD 2>/dev/null; then
  warn "This checkout does not have commit $REQUIRED_COMMIT (#333). Pull main and deploy it first."
  exit 1
fi
printf '  %s✓%s main has #333\n' "$GREEN" "$RESET"
running=$(dc ps --status running --services 2>/dev/null || true)
for service in postgres web forward-test ib-gateway; do
  if grep -qx "$service" <<<"$running"; then
    printf '  %s✓%s %s runs\n' "$GREEN" "$RESET" "$service"
  else
    warn "$service does not run. Start ATrade with ./start run (ib-gateway needs COMPOSE_PROFILES=ibkr)."
    exit 1
  fi
done
health=$(docker inspect --format '{{.State.Health.Status}}' "$(dc ps -q ib-gateway)" 2>/dev/null || echo unknown)
if [[ "$health" == healthy ]]; then
  printf '  %s✓%s ib-gateway is healthy\n' "$GREEN" "$RESET"
else
  warn "ib-gateway is $health. The import does not need it, but the IBKR stock split check (stage 6) does."
fi
mkdir -p "$DAILY_DIR" "$HOURLY_DIR"
free_gb=$(df -BG --output=avail "$ATRADE_DIR/data" | tail -1 | tr -dc '0-9')
if (( free_gb < MIN_FREE_GB )); then
  warn "Only ${free_gb} GB free. The files and the database need about ${MIN_FREE_GB} GB."
  confirm "Continue anyway?" || exit 1
else
  printf '  %s✓%s %s GB free\n' "$GREEN" "$RESET" "$free_gb"
fi
note "Run this wizard in zellij (or another terminal multiplexer): an SSH disconnect then does not stop it."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Databento credit"
say "All purchases use the new user credit (125 USD). The credit expires 6 months after sign-up."
open_url "https://databento.com/portal"
step "Sign in. Find the billing page that shows the credit balance and its expiry date."
step "Make sure that about 110 USD of the credit is left (daily about 87 USD, hourly about 24 USD)."
note "If the portal looks different, look for 'Billing' or 'Usage' in the side menu."
confirm "Is about 110 USD of the credit left, and not expired?" || { warn "Stop: the purchase needs the credit."; exit 1; }

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Databento API key"
open_url "https://databento.com/portal/keys"
step "Copy an API key (it starts with 'db-'), or make a new key."
ask_secret DATABENTO_API_KEY "Paste the API key (input is hidden):"
[[ "$DATABENTO_API_KEY" == db-* ]] || warn "The key does not start with 'db-'. Make sure that it is correct."
write_env DATABENTO_API_KEY "$DATABENTO_API_KEY"
say "Recreate web and forward-test, so that they get the key:"
dc up -d web forward-test
note "forward-test uses the key for the quarterly universe update (about 1.3 USD each quarter)."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Buy the daily bars and statistics"
mapfile -t bought_kinds < <([[ -f "$DAILY_DIR/jobs.txt" ]] && awk '{print $1}' "$DAILY_DIR/jobs.txt" || true)
if (( ${#bought_kinds[@]} >= 5 )); then
  say "The 5 daily jobs are bought already ($DAILY_DIR/jobs.txt):"
  sed 's/^/    /' "$DAILY_DIR/jobs.txt"
  pause
else
  (( ${#bought_kinds[@]} )) && say "Bought already: ${bought_kinds[*]}. The wizard buys only the others."
  say "The cost of the 5 batch jobs (reading the cost is free):"
  web_python "$DAILY_JOBS_PY" cost
  if confirm "Buy the jobs that are not bought yet? This uses the credit."; then
    web_python "$DAILY_JOBS_PY" submit "${bought_kinds[@]}" | tee -a "$DAILY_DIR/jobs.txt"
    printf '  %s✓%s job IDs saved in %s\n' "$GREEN" "$RESET" "$DAILY_DIR/jobs.txt"
    pause
  else
    warn "Nothing bought. Run the wizard again when you are ready."
    exit 0
  fi
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Import the daily bars"
wait_for_jobs "$DAILY_DIR/jobs.txt"
say "Download and import. The import sends no request to IBKR. At the end, it calculates the quarterly universe."
import_directory "$DAILY_DIR"
printf '  %s✓%s daily import done\n' "$GREEN" "$RESET"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Start the IBKR stock split check"
if docker ps --format '{{.Names}}' | grep -qx "$SPLIT_CHECK_CONTAINER"; then
  say "The check runs already."
else
  dc run --rm --detach --name "$SPLIT_CHECK_CONTAINER" web python -m atrade.app.ibkr_split_check
  printf '  %s✓%s started in the background (container %s)\n' "$GREEN" "$RESET" "$SPLIT_CHECK_CONTAINER"
fi
say "Read its log in another pane:"
note "  docker logs --follow $SPLIT_CHECK_CONTAINER"
say "It can run for many hours. It continues after a pacing violation or a Gateway restart."
say "It stops when no instrument waits. If it stops early, run this wizard again: stage 6 starts it again."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cost of the hourly bars"
if [[ -s "$HOURLY_DIR/jobs.txt" ]]; then
  say "Some hourly jobs are bought already. The next stage buys only the missing quarters."
  pause
else
  say "The purchase list: one line for each quarter, then the total (free, buys nothing):"
  dc run --rm web python -m atrade.app.databento_import --hourly-cost
  confirm "Is the total in the credit that is left?" || { warn "Stop: nothing bought."; exit 0; }
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Buy and import the hourly bars"
mapfile -t bought_quarters < <([[ -f "$HOURLY_DIR/jobs.txt" ]] && awk '{print $1}' "$HOURLY_DIR/jobs.txt" || true)
if confirm "Buy the hourly batch jobs of the quarters that have no job yet? This uses the credit."; then
  web_python "$HOURLY_JOBS_PY" submit "${bought_quarters[@]}" | while read -r line; do
    if [[ "$line" == QUARTERS* ]]; then
      note "Quarters in the purchase list: ${line#QUARTERS }"
    else
      printf '%s\n' "$line" >> "$HOURLY_DIR/jobs.txt"
      note "bought $line"
    fi
  done
fi
wait_for_jobs "$HOURLY_DIR/jobs.txt"
import_directory "$HOURLY_DIR"
printf '  %s✓%s hourly import done\n' "$GREEN" "$RESET"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check the stock splits and symbol links"
say "These wait for your check (stock splits of the detection rule, symbol links):"
dc run --rm web python -m atrade.app.databento_check
step "Find each wrong stock split. Write its ID."
REJECT_IDS=""
ask REJECT_IDS "IDs to reject, separated by spaces (Enter for none):" || true
reject_args=()
for id in $REJECT_IDS; do reject_args+=(--reject-split "$id"); done
if confirm "Confirm all others${REJECT_IDS:+ and reject $REJECT_IDS}? A confirmed stock split changes the stored bars."; then
  dc run --rm web python -m atrade.app.databento_check --accept "${reject_args[@]}"
fi
note "The IBKR stock split check can add more detections (instruments without IBKR bars)."
note "When it is done, run this wizard again and do stage 9 again, or run: python -m atrade.app.databento_check"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check the result"
say "Quarterly US universe (expected: each quarter from 2018-10-01, 500 members each):"
psql_query "SELECT count(DISTINCT quarter_start_utc) AS quarters, min(quarter_start_utc)::date AS first, max(quarter_start_utc)::date AS last, count(*) AS members FROM us_universe_member WHERE currency = 'USD';"
say "IBKR stock split check:"
psql_query "SELECT count(*) FILTER (WHERE checked_end_utc IS NULL OR checked_end_utc < check_end_utc) AS waiting, count(*) AS total FROM ibkr_split_check;"
say "Tomorrow, after 18:00 ET, check that the daily bar update ran:"
note "  docker compose --file deploy/compose.yaml --env-file .env logs web | grep 'daily bar update'"
note "  Expected: 'The daily bar update of <day> saved the daily bars of <n> instruments.'"
say "Then tick the steps of issue #324 and measure the screen backtest time (#150)."
pause

finish
}

run_wizard "$@"; exit
